README.md:23:Project search and Search projects apply a name substring query alongside the Active/Archived filter. Task search and Search tasks apply a title substring query alongside completion, priority, and due-range filters. Searches ignore ASCII letter case and trim surrounding query whitespace only; internal whitespace and non-ASCII case remain significant. Blank queries match everything allowed by the other filters. Queries are page-local, reset when opening a page, and never modify saved data or summaries. Changing filters and editing, creating, or moving tasks retains the applied task query and immediately re-evaluates membership. Search stays usable in archived projects.
test/ui.test.js:732:function searchPage(pathname, projects, tasks = []) {
test/ui.test.js:765:async function applySearch(form, query) {
test/ui.test.js:770:test('project search is applied, ASCII-only, ordered and intersects archive filter', async () => {
test/ui.test.js:777:  const { app, writes } = searchPage('/', projects);
test/ui.test.js:779:  const search = formWithLabel(app, 'Project search');
test/ui.test.js:782:  assert.equal(search.children[1].value, '');
test/ui.test.js:783:  assert.equal(search.children[0].htmlFor, search.children[1].id);
test/ui.test.js:784:  assert.equal(search.children[1].type, 'text');
test/ui.test.js:785:  assert.equal(search.children[2].textContent, 'Search projects');
test/ui.test.js:786:  await applySearch(search, '  ALPHA  ');
test/ui.test.js:792:  assert.equal(search.children[1].value, 'ALPHA');
test/ui.test.js:795:  await applySearch(search, 'alpha  ');
test/ui.test.js:796:  await applySearch(search, 'alpha  p');
test/ui.test.js:798:  search.children[1].value = 'draft';
test/ui.test.js:801:  await applySearch(search, 'älpha');
test/ui.test.js:803:  await applySearch(search, 'ÄLPHA');
test/ui.test.js:805:  await applySearch(search, ' \t ');
test/ui.test.js:808:  await applySearch(search, 'alpha');
test/ui.test.js:811:  const reopened = searchPage('/', projects);
test/ui.test.js:813:  assert.equal(formWithLabel(reopened.app, 'Project search').children[1].value, '');
test/ui.test.js:818:  test(`task search intersects all filters and retains applied state (${archived ? 'archived' : 'active'})`, async () => {
test/ui.test.js:825:    const { app, writes } = searchPage('/projects/1', [project, { id: 2, name: 'Destination', archived: false }], tasks);
test/ui.test.js:827:    const search = formWithLabel(app, 'Task search');
test/ui.test.js:834:    assert.equal(search.children[1].value, '');
test/ui.test.js:835:    assert.equal(search.children[0].htmlFor, search.children[1].id);
test/ui.test.js:836:    assert.equal(search.children[2].textContent, 'Search tasks');
test/ui.test.js:837:    await applySearch(search, ' ALPHA ');
test/ui.test.js:846:    await applySearch(search, 'alpha p');
test/ui.test.js:848:    await applySearch(search, '   ');
test/ui.test.js:850:    await applySearch(search, 'alpha');
test/ui.test.js:858:      await applySearch(row().children[2], 'Alpha renamed');
test/ui.test.js:860:      await applySearch(formWithLabel(app, 'New project name'), 'Renamed project');
test/ui.test.js:864:      await applySearch(formWithLabel(app, 'Task title'), 'Alpha new');
test/ui.test.js:866:      await applySearch(row().children[2], 'No match');
test/ui.test.js:868:      await applySearch(search, 'no match');
test/ui.test.js:870:      await applySearch(row().children[5], '2000-03-01');
test/ui.test.js:888:      assert.equal(search.children[1].value, 'no match');
test/ui.test.js:894:    const reopened = searchPage('/projects/1', [project], tasks);
test/ui.test.js:896:    assert.equal(formWithLabel(reopened.app, 'Task search').children[1].value, '');
public/app.js:29:function asciiLower(value) {
public/app.js:33:function searchControl(labelText, buttonText, id, onApply) {
public/app.js:47:    query = asciiLower(input.value);
public/app.js:50:  return { form, matches: (text) => asciiLower(text).includes(query) };
public/app.js:112:  const search = searchControl('Project search', 'Search projects', 'project-search', renderProjects);
public/app.js:116:        && search.matches(project.name))
public/app.js:147:  app.append(form, filters, search.form, list);
public/app.js:237:  const search = searchControl('Task search', 'Search tasks', 'task-search', renderTasks);
public/app.js:240:      search.matches(task.title) &&
public/app.js:396:  app.append(form, filters, rangeForm, search.form, defaultPriorityControl(project), list);
